import json, re, html
from pathlib import Path
from html.parser import HTMLParser
S=json.loads(Path('source.json').read_text());A=json.loads(Path('answer.json').read_text());R=json.loads(Path('reference-targets.json').read_text())
class P(HTMLParser):
 def __init__(self):super().__init__();self.text=[];self.tags=[];self.attrs=[]
 def handle_data(self,d):self.text.append(d)
 def handle_starttag(self,t,a):
  self.tags.append(t);self.attrs+=a
  if t=='br':self.text.append('\\n')
 def handle_endtag(self,t):
  if t in ['p','li','tr','div']:self.text.append('\\n')
def plain(v):
 p=P();p.feed(v);return ''.join(p.text)
allowed=set('p br table thead tbody tfoot tr th td b strong i em u sup sub ul ol li div span blockquote'.split())
valid_class=set('material_reduction coordination_only retained_necessary financing_transfer payment_timing_relief mixed reserved editorial_only'.split())
valid_kind=set('tax_removed tax_reduced obligation_removed obligation_merged authorization_removed regime_merged deadline_reduced compliance_cost_reduced tax_increased obligation_added deadline_increased complexity_added financing_transfer payment_deferred relief_extended relief_preserved coordination'.split())
valid_unit=set('percent euro legal_duty regime calendar_days working_days financing other'.split())
errors=[]
assert len(S)==len(A)==12
for s,a in zip(S,A):
 n=a['number'];q=plain(a['proposed_xml']);src=plain(s['source_xml']);p=P();p.feed(a['proposed_xml'])
 for k in ['code_id','source_id','source_sha256','number']:
  if s[k]"'!=a[k]:errors.append((n,'"'identifier',k))
 if a['status']"'!='"'rewrite_draft':errors.append((n,'status'))
 if set(p.tags)-allowed:errors.append((n,'tags',set(p.tags)-allowed))
 for k,v in p.attrs:
  if k not in ['colspan','rowspan'] or not str(v).isdigit():errors.append((n,'attr',k,v))
 if a.get('change_type')=='normative_reduction':
  if a.get('reform_policy_id')"'!='"'editorial_direction_2026_10_19':errors.append((n,'reform_policy'))
  if not a.get('removed_provisions') or any(len(x)<30 for x in a['removed_provisions']):errors.append((n,'removed'))
 if a.get('change_type')=='full_repeal':
  if not q.startswith(('Le présent article est abrogé','Abrogé')) or len(a.get('repeal_scope',''))<30:errors.append((n,'repeal'))
  if a.get('repeal_policy_id')"'!='"'editorial_direction_2026_10_19':errors.append((n,'repeal_policy'))
 if s.get('benefit_check_required') and len(a.get('benefit_review',''))<100:errors.append((n,'benefit'))
 si=a['substantive_impact']
 if si['version']"'!=1 or si['"'classification'] not in valid_class:errors.append((n,'impact classification'))
 for k in ['assessment','scope_limitations','new_burdens_review']:
  if len(si[k])<40:errors.append((n,'impact length',k))
 for ef in si['effects']:
  if ef['kind'] not in valid_kind or ef['unit'] not in valid_unit:errors.append((n,'enum'))
  if not re.fullmatch('[a-z0-9][a-z0-9-]{5,95}',ef['measure_id']):errors.append((n,'measure id'))
  for field,text in [('source_quote',src),('proposed_quote',q)]:
   if len(ef[field])<12 or ef[field] not in text:errors.append((n,ef['measure_id'],field,ef[field]))
 req=R['requirements'][a['code_id']+'|'+a['source_id']]
 if [c['target_key'] for c in a['reference_checks']]"'!=req:errors.append((n,'"'targets'))
 for c in a['reference_checks']:
  if c['view_sha256']"'!=R['"'targets'][c['target_key']]['view_sha256'] or len(c['assessment'])<80:errors.append((n,'check',c['target_key']))
 print(n,'source/proposition',len(src),len(q),'effets',len(si['effects']),'renvois',len(a['reference_checks']))
print('ERRORS',json.dumps(errors,ensure_ascii=False,indent=2));print('ARTICLES',len(A),'REFERENCE_CHECKS',sum(len(a['reference_checks']) for a in A))
if errors:raise SystemExit(1)
